export interface ICategory {
	name: string
	typeValue: string
	contentType: ContentType
	folder: string
	// The section is folded on the Library tab; kept across restarts.
	collapsed?: boolean
}

// One column of the statistics: a category's best-rated titles, or the most
// frequent values of a frontmatter property across the whole library.
export interface IStatsTop {
	kind: 'category' | 'property'
	// The category's Type value, or the property name as the notes write it.
	key: string
}

export interface IStatsSettings {
	watchTime: boolean
	// The columns, in the order they were added.
	tops: IStatsTop[]
}

export interface ISortState {
	key: string
	asc: boolean
}

export interface ILibrarySettings {
	categories: ICategory[]
	omdbApiKey: string
	googleBooksApiKey: string
	rawgApiKey: string
	comicVineApiKey: string
	anilistClientId: string
	anilistToken: string
	coverProperty: string
	tmdbApiKey: string
	sortState: Record<string, ISortState>
	statsCollapsed: boolean
	stats: IStatsSettings
	enrichMarks: Record<string, string>
}

export const DEFAULT_SETTINGS: ILibrarySettings = {
	categories: [],
	omdbApiKey: '',
	googleBooksApiKey: '',
	rawgApiKey: '',
	comicVineApiKey: '',
	anilistClientId: '',
	anilistToken: '',
	coverProperty: 'Cover',
	tmdbApiKey: '',
	sortState: {},
	statsCollapsed: false,
	stats: {
		watchTime: true,
		tops: [
			{ kind: 'property', key: 'Genre' },
			{ kind: 'property', key: 'Creator' },
			{ kind: 'property', key: 'Cast' }
		]
	},
	enrichMarks: {}
}
